	switch r.Method {
	case http.MethodGet:
		encoded := r.URL.Query().Get("dns")
		if len(encoded) > base64.RawURLEncoding.EncodedLen(dns.MaxMsgSize) {
			http.Error(w, http.StatusText(http.StatusRequestEntityTooLarge), http.StatusRequestEntityTooLarge)
			return
		}

encoded := r.URL.Query().Get("dns")
if len(encoded) > base64.RawURLEncoding.EncodedLen(dns.MaxMsgSize) {
